// SPDX-License-Identifier: 0BSD
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { format, resolveConfig } from 'prettier'

import { BG_THEME } from '../src/providers/PersonalizationProvider/constants/bg_theme'
import colors from '../src/providers/PersonalizationProvider/constants/theme_color_hex'
import { getColorPalette } from '../src/providers/PersonalizationProvider/utils/themeColors'

const header =
  '/* SPDX-License-Identifier: 0BSD */\n/* Generated by packages/ui/scripts/generate-themes.ts. */\n'
function declarations(variables: Record<string, string>) {
  return Object.entries(variables)
    .map(([name, value]) => '  ' + name + ': ' + value + ';')
    .join('\n')
}
function paletteVariables(kind: string, shades: Record<string, string>) {
  return Object.fromEntries(
    Object.entries(shades).map(([level, value]) => [
      '--color-' + kind + '-' + level,
      value
    ])
  )
}
function block(selector: string, kind: string, shades: Record<string, string>) {
  return (
    selector + ' {\n' + declarations(paletteVariables(kind, shades)) + '\n}\n'
  )
}
const typeScale = {
  xs: [0.75, 1],
  sm: [0.875, 1.25],
  base: [1, 1.5],
  lg: [1.125, 1.75],
  xl: [1.25, 1.75],
  '2xl': [1.5, 2],
  '3xl': [1.875, 2.25],
  '4xl': [2.25, 2.5],
  '5xl': [3, 3],
  '6xl': [3.75, 3.75],
  '7xl': [4.5, 4.5],
  '8xl': [6, 6],
  '9xl': [8, 8]
}
const tokens: Record<string, string> = {
  '--custom-font-scale': '1',
  '--custom-border-radius-multiplier': '1',
  '--spacing': 'calc(.25rem * var(--custom-font-scale))',
  '--color-dangerous': '#D94B45',
  '--custom-shadow': '0 2px 7px #00000012',
  ...paletteVariables('bg', BG_THEME.zillion),
  ...paletteVariables('custom', getColorPalette('#6086B8', 'theme'))
}
for (const [name, [size, line]] of Object.entries(typeScale)) {
  tokens['--text-' + name] = 'calc(' + size + 'rem * var(--custom-font-scale))'
  tokens['--text-' + name + '--line-height'] = String(line / size)
}
for (const [index, name] of ['sm', 'md', 'lg', 'xl', '2xl', '3xl'].entries()) {
  tokens['--radius-' + name] =
    'calc(' + (index + 1) * 4 + 'px * var(--custom-border-radius-multiplier))'
}
const outputs = {
  'background.css':
    header +
    Object.entries(BG_THEME)
      .map(([name, palette]) => block('.bg-' + name, 'bg', palette))
      .join('\n'),
  'foreground.css':
    header +
    Object.entries(colors)
      .map(([name, color]) =>
        block(
          '.theme-' +
            name.replace(/[A-Z]/g, letter => '-' + letter.toLowerCase()),
          'custom',
          getColorPalette(color, 'theme')
        )
      )
      .join('\n'),
  'index.css':
    header +
    "@import './background.css';\n@import './foreground.css';\n\n:where(:root) {\n" +
    declarations(tokens) +
    '\n}\n.dark { --custom-shadow: none; }\n'
}
async function generate() {
  for (const [name, source] of Object.entries(outputs)) {
    const path = fileURLToPath(
      new URL('../src/styles/themes/' + name, import.meta.url)
    )
    const output = await format(source, {
      ...(await resolveConfig(path)),
      filepath: path
    })
    if (process.argv.includes('--check')) {
      if (
        readFileSync(path, 'utf8').replace(/\r/g, '') !==
        output.replace(/\r/g, '')
      )
        throw Error(name + ' is out of date')
    } else {
      readFileSync(path, 'utf8')
      writeFileSync(path, output)
    }
  }
  console.log(
    process.argv.includes('--check')
      ? 'Theme files match their sources'
      : 'Generated named themes and design tokens'
  )
}
void generate().catch(error => {
  console.error(error.message)
  process.exitCode = 1
})
